FixedCamera::FixedCamera()=default; FixedCamera::~FixedCamera()=default; void FixedCamera::ChangeToFocus(int id){if(id<0)id=0;if(id!=focusUnit_){focusUnit_=id;direction_={};flipped_=false;}} void FixedCamera::UpdateDirection(){fates::decomp_detail::FixedCameraUpdateDirection(*this);} void FixedCamera::UpdateParam(const CameraParam&p){fates::decomp_detail::FixedCameraUpdateParam(*this,p);} void FixedCamera::Tick(){UpdateDirection();CameraParam p;CamUtil::CalcFixedCamera(&p,flipped_);UpdateParam(p);} void FixedCamera::Enter(){} void FixedCamera::Leave(){} int FixedCamera::GetModeType()const{return 1;} bool FixedCamera::CanChangeMode()const{return false;} bool FixedCamera::CanLookAround()const{return true;} bool FixedCamera::IsHitPos()const{return true;} bool FixedCamera::IsHitArea()const{return true;} bool FixedCamera::IsHitFovy()const{return false;}
